using System;using System.Collections.Generic;using System.IO;using System.Linq;using UnityEngine;
namespace RoadRush
{
 // Reconstructs published authority only. Source authoring/grade solving never
 // runs here. Construction validates before publishing any prepared state.
 public sealed class RoadElevationField
 {
  sealed class State{internal RoadElevationCurve Curve;internal RoadElevationHorizontalFrame Frame;internal bool Bevel;internal List<Binding> Bindings=new List<Binding>();}
  sealed class Binding{internal string PatchId;internal RoadJunctionArmDto Arm;internal RoadElevationCollar Collar;}
  readonly Dictionary<string,State> states=new Dictionary<string,State>(StringComparer.Ordinal);readonly RoadElevationProfileDto[] controls;readonly RoadJunctionPatchDto[] patches;readonly RoadSyntheticAnchorDto[] anchors;readonly RoadContinuationDto[] continuations;
  public string SourceDigest{get;}public int RoadCount=>states.Count;
  public RoadElevationField(GeoRoad[] roads,RoadElevationProfileDto[] profiles,RoadJunctionPatchDto[] patches,RoadWidthProfileDto[] widths=null,RoadSyntheticAnchorDto[] anchors=null,RoadContinuationDto[] continuations=null)
  {
   if(roads==null||roads.Length<1||roads.Length>10000||profiles==null||profiles.Length>10000||patches!=null&&patches.Length>10000||anchors!=null&&anchors.Length>1024||continuations!=null&&continuations.Length>10000)throw new InvalidDataException("Elevation owner input budget");long boundaryBudget=0,armBudget=0,spanBudget=0;foreach(var patch in patches??Array.Empty<RoadJunctionPatchDto>()){if(patch==null||patch.boundary==null||patch.arms==null||patch.boundary.Length>65||patch.arms.Length>32)throw new InvalidDataException("Patch clone preflight");boundaryBudget+=patch.boundary.Length;armBudget+=patch.arms.Length;foreach(var arm in patch.arms){if(arm==null||arm.spans==null||arm.spans.Length>64)throw new InvalidDataException("Span clone preflight");spanBudget+=arm.spans.Length;}}if(boundaryBudget>65536||armBudget>65536||spanBudget>262144)throw new InvalidDataException("Elevation clone total budget");string initialSource=RoadSourceIdentity.Compute(roads);RoadElevationProfileDto.Validate(profiles,roads,widths);
   var source=roads?.Select(CloneRoad).ToArray()??throw new InvalidDataException("Missing elevation source");controls=profiles?.Select(CloneProfile).ToArray()??throw new InvalidDataException("Missing elevation controls");this.patches=(patches??Array.Empty<RoadJunctionPatchDto>()).Select(ClonePatch).ToArray();this.anchors=(anchors??Array.Empty<RoadSyntheticAnchorDto>()).Select(CloneAnchor).ToArray();this.continuations=(continuations??Array.Empty<RoadContinuationDto>()).Select(CloneContinuation).ToArray();var w=widths?.Select(CloneWidth).ToArray();
   SourceDigest=RoadSourceIdentity.Compute(source);if(SourceDigest!=initialSource)throw new InvalidDataException("Elevation source changed during construction");RoadElevationProfileDto.Validate(controls,source,w);RoadSyntheticAnchorDto.Validate(this.anchors,source,controls,SourceDigest);var registry=new RoadContinuationAuthority(source,controls,w,this.anchors,this.continuations);RoadJunctionPatchDto.Validate(this.patches,source,controls,w,this.anchors,registry);RoadTopologyAuthority.Validate(source,this.patches,this.anchors,registry);RoadJunctionAuthorityProof.Validate(this.patches,source,controls,w,registry);
   var widthsField=w==null?null:new EffectiveRoadWidthField(w,source);var plan=RoadMarkingPlan.BuildFrames(source,(r,s)=>widthsField==null?r.width:widthsField.At(r,s));var byId=controls.ToDictionary(p=>p.roadId,StringComparer.Ordinal);
   foreach(var road in source){var curve=new RoadElevationCurve(road,byId[road.id]);plan.Frames.TryGetValue(road.id,out var frame);states.Add(road.id,new State{Curve=curve,Frame=frame==null?null:new RoadElevationHorizontalFrame(curve.Metric,frame),Bevel=widthsField!=null&&widthsField.UseBevelBoundary(road)});}
   var curves=states.ToDictionary(p=>p.Key,p=>p.Value.Curve,StringComparer.Ordinal);foreach(var patch in this.patches.OrderBy(p=>p.id,StringComparer.Ordinal))foreach(var arm in patch.arms){var binding=new Binding{PatchId=patch.id,Arm=arm,Collar=new RoadElevationCollar(curves,patch,arm)};for(int i=0;i<binding.Collar.Path.SpanCount;i++)states[binding.Collar.Path.GetSpan(i).RoadId].Bindings.Add(binding);}
  }
  public RoadElevationCurve.Sample Evaluate(string roadId,double sourceS,double physicalLateral)
  {var state=Get(roadId);state.Curve.Metric.FrameAtSource(sourceS,out var centre,out var forward,out var right);return EvaluateAtFrame(roadId,sourceS,physicalLateral,centre,right,forward,Vector3.zero);}
  public RoadElevationCurve.Sample EvaluateAtFrame(string roadId,double sourceS,double nominalLateral,Vector3 centre,Vector3 right,Vector3 dCentreDH,Vector3 dRightDH,double dNominalLateralDH=0)
  {
   var state=Get(roadId);Binding selected=null;bool selectedInterior=false;foreach(var binding in state.Bindings){if(!binding.Collar.Path.TryLocate(roadId,sourceS,out double at,out _))continue;double end=binding.Collar.Path.HorizontalLength;bool interior=at<end-1e-8;if(selected!=null&&selected.PatchId!=binding.PatchId&&selectedInterior&&interior)throw new InvalidDataException("Ambiguous elevation collar authority");if(selected==null||interior&&!selectedInterior){selected=binding;selectedInterior=interior;}}
   return selected==null?state.Curve.EvaluateAtFrame(sourceS,nominalLateral,right,dRightDH,dNominalLateralDH):selected.Collar.EvaluateAtFrame(roadId,sourceS,nominalLateral,centre,right,dCentreDH,dRightDH,dNominalLateralDH);
  }
  public Vector3 Point(string roadId,double sourceS,double nominalLateral)
  {var state=Get(roadId);Vector3 centre,right,forward,derivative;if(state.Frame!=null)state.Frame.At(sourceS,out centre,out right,out forward,out derivative,false,state.Bevel);else{state.Curve.Metric.FrameAtSource(sourceS,out centre,out forward,out right);derivative=Vector3.zero;}var result=centre+right*(float)nominalLateral;result.y=(float)EvaluateAtFrame(roadId,sourceS,nominalLateral,centre,right,forward,derivative).Elevation;return result;}
  State Get(string id){if(id==null||!states.TryGetValue(id,out var state))throw new InvalidDataException("Foreign elevation road identity");return state;}
  public RoadElevationProfileDto[] CopyProfileSnapshot()=>controls.Select(CloneProfile).ToArray();public RoadJunctionPatchDto[] CopyPatchSnapshot()=>patches.Select(ClonePatch).ToArray();public RoadSyntheticAnchorDto[] CopySyntheticSnapshot()=>anchors.Select(CloneAnchor).ToArray();public RoadContinuationDto[] CopyContinuationSnapshot()=>continuations.Select(CloneContinuation).ToArray();
  static GeoRoad CloneRoad(GeoRoad r){if(r==null||r.points==null||r.points.Length<2||r.points.Length>10000||r.sourceNodeIds==null||r.sourceNodeIds.Length!=r.points.Length)throw new InvalidDataException("Elevation road snapshot shape");return new GeoRoad{id=r.id,start=r.start,end=r.end,name=r.name,kind=r.kind,width=r.width,maxVehicleHeight=r.maxVehicleHeight,limit=r.limit,oneWay=r.oneWay,layer=r.layer,bridge=r.bridge,tunnel=r.tunnel,points=r.points==null?null:(Vector3[])r.points.Clone(),sourceNodeIds=r.sourceNodeIds==null?null:(string[])r.sourceNodeIds.Clone()};}
  static RoadWidthProfileDto CloneWidth(RoadWidthProfileDto p){if(p==null||p.distances==null||p.widths==null||p.derivatives==null||p.distances.Length>512||p.widths.Length!=p.distances.Length||p.derivatives.Length!=p.distances.Length)throw new InvalidDataException("Width snapshot shape");return new RoadWidthProfileDto{roadId=p.roadId,bevelBoundary=p.bevelBoundary,distances=(float[])p.distances.Clone(),widths=(float[])p.widths.Clone(),derivatives=(float[])p.derivatives.Clone()};}
  static RoadElevationProfileDto CloneProfile(RoadElevationProfileDto p){if(p==null||p.distances==null||p.distances.Length<2||p.distances.Length>512||p.elevations==null||p.elevations.Length!=p.distances.Length||p.gradeDerivatives==null||p.gradeDerivatives.Length!=p.distances.Length||p.crossfalls==null||p.crossfalls.Length!=p.distances.Length||p.crownRates==null||p.crownRates.Length!=p.distances.Length)throw new InvalidDataException("Elevation control snapshot shape");return new RoadElevationProfileDto{roadId=p.roadId,distances=p.distances==null?null:(double[])p.distances.Clone(),elevations=p.elevations==null?null:(float[])p.elevations.Clone(),gradeDerivatives=p.gradeDerivatives==null?null:(float[])p.gradeDerivatives.Clone(),crossfalls=p.crossfalls==null?null:(float[])p.crossfalls.Clone(),crownRates=p.crownRates==null?null:(float[])p.crownRates.Clone(),crownSmooth=p.crownSmooth};}
  static RoadJunctionPatchDto ClonePatch(RoadJunctionPatchDto p){if(p==null||p.boundary==null||p.boundary.Length>65||p.arms==null||p.arms.Length>32)throw new InvalidDataException("Elevation patch snapshot budget");return new RoadJunctionPatchDto{id=p.id,nodeId=p.nodeId,kind=p.kind,syntheticAnchorId=p.syntheticAnchorId,layer=p.layer,centre=p.centre,planeGradient=p.planeGradient,boundary=p.boundary==null?null:(Vector2[])p.boundary.Clone(),arms=p.arms?.Select(a=>a==null?null:new RoadJunctionArmDto{roadId=a.roadId,sourceDistance=a.sourceDistance,direction=a.direction,coreLength=a.coreLength,collarLength=a.collarLength,spans=a.spans?.Select(t=>t==null?null:new RoadJunctionSpanDto{roadId=t.roadId,fromSourceDistance=t.fromSourceDistance,toSourceDistance=t.toSourceDistance}).ToArray()}).ToArray()};}
  static RoadContinuationDto CloneContinuation(RoadContinuationDto c){if(c==null)throw new InvalidDataException("Null continuation");return new RoadContinuationDto{id=c.id,nodeId=c.nodeId,roadA=c.roadA,roadB=c.roadB,atEndA=c.atEndA,atEndB=c.atEndB};}
  static RoadSyntheticAnchorDto CloneAnchor(RoadSyntheticAnchorDto a){if(a==null)throw new InvalidDataException("Null synthetic anchor");return new RoadSyntheticAnchorDto{id=a.id,kind=a.kind,parentRoadId=a.parentRoadId,parentSourceDistance=a.parentSourceDistance,connectorRoadId=a.connectorRoadId,connectorSourceDistance=a.connectorSourceDistance,sourcePin=a.sourcePin};}
 }
}
